use vstd::prelude::*;

verus! {

fn r_(a: Vec<i8>, b: Vec<i8>) -> (res: Vec<i8>)
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let mut out: Vec<i8> = Vec::new();

    // Copy a into out
    let mut i: usize = 0;
    while i < a.len()
        invariant
            out@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> out@[k] == a@[k],
        decreases
            a.len() - i,
    {
        out.push(a[i]);
        i += 1;
    }

    // Now append b into out
    let a_len: usize = a.len();
    let mut j: usize = 0;
    while j < b.len()
        invariant
            out@.len() == a_len as int + j as int,
            // prefix from a preserved
            forall|k: int| 0 <= k < a_len as int ==> out@[k] == a@[k],
            // appended portion equals b[0..j)
            forall|k: int| 0 <= k < j as int ==> out@[a_len as int + k] == b@[k],
        decreases
            b.len() - j,
    {
        out.push(b[j]);
        j += 1;
    }

    // Postcondition follows from loop invariants
    out
}

} // verus!

